{
    if (!s_theme_rebuild_pending) {
        return;
    }

    if (lvgl_page_current_id() != (int)BICYCLE_PM_ID_MAP ||
        lvgl_page_nav_busy()) {
        return;                    /* 不在主界面/转场还没走完 ⇒ 等（见上） */
    }

    s_theme_rebuild_pending = false;
    helm_shell_rebuild();
}

