static void helm_dial_smooth5(const int16_t *src, uint8_t n)
{
    uint8_t i;

    for (i = 0; i < n; i++) {
        int lo = (int)i - 2;
        int hi = (int)i + 2;
        int sum = 0;
        int cnt;
        int k;

        if (lo < 0) {
            lo = 0;
        }
        if (hi > (int)n - 1) {
            hi = (int)n - 1;
        }
        cnt = hi - lo + 1;
        for (k = lo; k <= hi; k++) {
